mapper.select:
/* SampleMapper.selectSample 사용 중인 공통코드 그룹을 조회한다. */
SELECT WRK_MDUL_CD,
       COMM_CTG_CD,
       COMM_CTG_NM
FROM TB_COMM_CD_M
WHERE WRK_MDUL_CD = #{wrkMdulCd}
  AND COMM_CTG_CD = #{commCtgCd}
  AND USE_YN = 'Y'

/* SampleMapper.selectSampleCodeList 공통코드 그룹의 사용 중인 상세코드 목록을 정렬순번 순으로 조회한다. */
SELECT COMM_CTG_DTL_CD,
       COMM_CTG_DTL_NM,
       ALIN_SEQ
FROM TB_COMM_CD_D
WHERE WRK_MDUL_CD = #{wrkMdulCd}
  AND COMM_CTG_CD = #{commCtgCd}
  AND USE_YN = 'Y'
ORDER BY ALIN_SEQ, COMM_CTG_DTL_CD
